import type { SearchcraftCore } from '@classes';
import { registry } from '@classes/CoreInstanceRegistry';
import { Component, Element, Prop, State, Watch, h } from '@stencil/core';
import type {
  AdClientResponseItem,
  PopoverNoResultsTemplate,
  PopoverResultMappings,
  SearchClientResponseItem,
  SearchResultTemplate,
  SearchResultTemplateData,
} from '@types';
import { html, safeUrl } from '@utils';
import classNames from 'classnames';
import DOMPurify from 'dompurify';

/**
 * This web component is designed to display search results in a popover container that dynamically appears when the user interacts with a search input field, or when a popover-button is pressed.
 *
 * @react-import
 * ```jsx
 * import { SearchcraftPopoverForm } from "@searchcraft/react-sdk";
 * ```
 *
 * @vue-import
 * ```jsx
 * import { SearchcraftPopoverForm } from "@searchcraft/vue-sdk";
 * ```
 *
 * @js-example
 * ```html
 * <!-- index.html -->
 * <searchcraft-popover-form type="inline" />
 * ```
 *
 * ```js
 * // index.js
 * const popoverForm = document.querySelector('searchcraft-popover-form');
 *
 * popoverForm.popoverResultMappings = {};
 *
 * // Or render each result with a template instead of `popoverResultMappings`.
 * popoverForm.template = (item, index, { html, safeUrl }) => html`
 *  <a href="${safeUrl(item.url)}">${item.title}</a>
 * `;
 *
 * // Change the message shown when a search returns no results.
 * popoverForm.noResultsTemplate = ({ searchTerm }, { html }) => html`
 *  <p>Nothing matched "${searchTerm}".</p>
 * `;
 * ```
 *
 * @react-example
 * ```jsx
 * <SearchcraftPopoverForm type="inline" popoverResultMappings={[]} />
 * ```
 *
 * @vue-example
 * ```jsx
 * <SearchcraftPopoverForm type="inline" :popoverResultMappings="[]"" />
 * ```
 *
 */
@Component({
  tag: 'searchcraft-popover-form',
  shadow: false,
})
export class SearchcraftPopoverForm {
  /**
   * The type of popover form to render.
   * - `inline` - Renders inline with the rest of the content on the page. The search results pop over the page content.
   * - `fullscreen` - Renders in fullscreen view. Used together with the `searchcraft-popover-button` component.
   * - `modal` - Renders in a modal view. Used together with the `searchcraft-popover-button` component.
   */
  @Prop() type?: 'inline' | 'fullscreen' | 'modal' = 'inline';
  /**
   * Formats the content rendered for each result.
   */
  @Prop() popoverResultMappings?: PopoverResultMappings;
  /**
   * A callback function responsible for rendering a result. When provided, it is used instead of `popoverResultMappings`.
   * Pass URLs from the result through the `safeUrl` helper before placing them in an `href` or `src`.
   * Never place result values in event handler attributes such as `onclick`, or in `style`.
   */
  @Prop() template?: SearchResultTemplate<SearchResultTemplateData>;
  /**
   * A callback function responsible for rendering the message shown when a search returns no results.
   * When it is not provided, the popover shows `No results found for "<search term>".`
   * The returned markup is sanitized with DOMPurify, which removes scripts, event handler
   * attributes such as `onclick`, and links with schemes it does not allow, such as an app's own scheme.
   */
  @Prop() noResultsTemplate?: PopoverNoResultsTemplate;
  /**
   * The hotkey that activates the popover.
   */
  @Prop() hotkey?: string = 'k';
  /**
   * The hotkey modifier that activates the popover. Used together with the `hotkey` prop.
   */
  @Prop() hotkeyModifier?: 'ctrl' | 'meta' | 'alt' | 'option' = 'meta';
  /**
   * The id of the Searchcraft instance that this component should use.
   */
  @Prop() searchcraftId?: string;
  /**
   * The input element's placeholder value.
   */
  @Prop() placeholderValue?: string = 'Enter Search';
  /**
   * The placeholder's render behavior.
   * 'hide-on-focus' - Hide the placeholder text immediately when the input form gains focus.
   * 'hide-on-text-entered' - Only hide the placeholder when the input form has text entered into it.
   */
  @Prop() placeholderBehavior?: 'hide-on-focus' | 'hide-on-text-entered';
  /**
   * Base URL for the "View all" footer link. The current search term will be appended (URL encoded).
   *
   * For example, in a CMS-backed site you might set this to `/?s=` so the final URL becomes `/?s=<search-term>`.
   */
  @Prop() viewAllResultsBaseUrl?: string;
  /**
   * Optional label for the "View All" footer button. Defaults to "View All".
   */
  @Prop() viewAllResultsLabel?: string;
  /**
   * Whether to display the AI generative summary box before the search results.
   * NOTE: This requires the usage of a read key that has "SUMMARY" permissions and either a subscription to Searchcraft Cloud with AI features enabled or a self-hosted model connected.
   */
  @Prop() showSummaryBox?: boolean = false;
  /**
   * The SDK variant used to render this component. Used for UTM attribution on the footer link.
   *
   * @internal
   */
  @Prop() sdkVariant?: 'js' | 'react' | 'vue' = 'js';

  @State() isPopoverVisibleInState = false;
  @State() searchClientResponseItems: SearchClientResponseItem[] = [];
  @State() adClientResponseItems: AdClientResponseItem[] = [];
  @State() searchTerm: string | undefined;
  @State() isSearchInProgress = false;
  /**
   * The search term of the most recent search response.
   */
  @State() completedSearchTerm: string | undefined;
  @State() isFocused = false;
  @State() breakpointSm = 576;
  @State() breakpointMd = 768;
  @State() breakpointLg = 992;
  @State() searchResultsPage;
  @State() searchResultsPerPage;

  @State() modalElement;

  @Element() hostElement!: HTMLElement;

  private unsubscribe: (() => void) | undefined;
  private cleanupCore?: () => void;
  core?: SearchcraftCore;

  onCoreAvailable(core: SearchcraftCore) {
    this.core = core;
    // Loads the breakpoint values into state
    const computedStyle = getComputedStyle(document.documentElement);
    this.breakpointSm = Number.parseFloat(
      computedStyle.getPropertyValue('--sc-breakpoint-sm').trim(),
    );
    this.breakpointMd = Number.parseFloat(
      computedStyle.getPropertyValue('--sc-breakpoint-md').trim(),
    );
    this.breakpointLg = Number.parseFloat(
      computedStyle.getPropertyValue('--sc-breakpoint-lg').trim(),
    );
    // Set popover visiblity in state
    this.isPopoverVisibleInState = core.store.getState().isPopoverVisible;

    // Add event listeners
    document.addEventListener('click', this.handleDocumentClick);
    document.addEventListener('keydown', this.handleDocumentKeyDown);

    // Subscribe to state events
    this.unsubscribe = core.store.subscribe((state) => {
      if (this.isPopoverVisibleInState !== state.isPopoverVisible) {
        this.handlePopoverVisibilityChange(state.isPopoverVisible);
      }

      this.searchClientResponseItems = [...state.searchClientResponseItems];
      this.adClientResponseItems = [...state.adClientResponseItems];
      this.searchTerm = state.searchTerm;
      this.isSearchInProgress = state.isSearchInProgress;
      const requestProperties = state.searchClientRequestProperties;
      this.completedSearchTerm =
        requestProperties && typeof requestProperties === 'object'
          ? requestProperties.searchTerm
          : undefined;
      this.searchResultsPage = state.searchResultsPage;
      this.searchResultsPerPage = state.searchResultsPerPage;
    });

    // Set hotkey and hotkeyModifier in state.
    core.store
      .getState()
      .setHotKeyAndHotKeyModifier(this.hotkey, this.hotkeyModifier);
  }

  connectedCallback() {
    this.cleanupCore = registry.useCoreInstance(
      this.searchcraftId,
      this.onCoreAvailable.bind(this),
    );
  }

  disconnectedCallback() {
    this.unsubscribe?.();
    this.cleanupCore?.();
    document.removeEventListener('click', this.handleDocumentClick);
    document.removeEventListener('keydown', this.handleDocumentKeyDown);
  }

  handleDocumentClick = (event: MouseEvent) => {
    if (!this.hostElement.contains(event.target as Node)) {
      this.isFocused = false;
    }
  };

  /**
   * Handles when popover visibility is changed in state
   */
  handlePopoverVisibilityChange(isVisible: boolean) {
    this.isPopoverVisibleInState = isVisible;
    document.body.style.overflow = isVisible ? 'hidden' : 'auto';
  }

  /**
   * Actions to perform when various keys are pressed within the popover form.
   */
  handleDocumentKeyDown = (event: KeyboardEvent) => {
    // Document-scoped actions
    if (event.key === this.hotkey) {
      this.handleHotkeyPressed(event);
    }

    // Document-scoped -> Popover-scoped keyboard event boundary
    if (!this.hostElement.contains(document.activeElement)) {
      return;
    }

    // Popover-scoped actions
    switch (event.key) {
      case 'ArrowDown':
      case 'ArrowUp':
        event.preventDefault();
        this.focusOnNextListItem(event.key);
        break;
      case 'Escape':
        this.core?.store.getState().setPopoverVisibility(false);
        break;
      case 'Enter':
        if (
          (event.metaKey || event.ctrlKey) &&
          this.viewAllResultsHref &&
          this.hasResultsToShow
        ) {
          event.preventDefault();
          this.navigateToViewAllResults();
        }
        break;
      default:
        return;
    }
  };

  handleInputInit = () => {
    const input = this.hostElement.querySelector(
      '.searchcraft-input-form-input',
    ) as HTMLInputElement | undefined;
    input?.focus();
  };

  /**
   * When popover is `inline` and the viewport is at the smallest breakpoint,
   * focusing on the input will open a modal version of the popover form.
   */
  handleInputFocus() {
    this.isFocused = true;

    if (
      this.type === 'inline' &&
      window.visualViewport &&
      window.visualViewport.width < this.breakpointSm
    ) {
      this.core?.store.getState().setPopoverVisibility(true);

      // Appends a popover form of type=`modal` to the body
      if (!this.modalElement) {
        this.modalElement = document.createElement('searchcraft-popover-form');
        this.modalElement.popoverResultMappings = this.popoverResultMappings;
        this.modalElement.template = this.template;
        this.modalElement.noResultsTemplate = this.noResultsTemplate;
        this.modalElement.setAttribute('type', 'fullscreen');
        this.modalElement.setAttribute('searchcraft-id', this.searchcraftId);
        if (this.placeholderValue) {
          this.modalElement.setAttribute(
            'placeholder-value',
            this.placeholderValue,
          );
        }
        if (this.placeholderBehavior) {
          this.modalElement.setAttribute(
            'placeholder-behavior',
            this.placeholderBehavior,
          );
        }
        if (this.viewAllResultsBaseUrl) {
          this.modalElement.setAttribute(
            'view-all-results-base-url',
            this.viewAllResultsBaseUrl,
          );
        }
        if (this.viewAllResultsLabel) {
          this.modalElement.setAttribute(
            'view-all-results-label',
            this.viewAllResultsLabel,
          );
        }
        document.body.appendChild(this.modalElement);
      }
    }
  }

  /**
   * Passes result rendering changes on to the fullscreen form created for small viewports,
   * which only receives these props when it is first created.
   */
  @Watch('popoverResultMappings')
  @Watch('template')
  @Watch('noResultsTemplate')
  syncModalElementResultRendering() {
    if (this.modalElement) {
      this.modalElement.popoverResultMappings = this.popoverResultMappings;
      this.modalElement.template = this.template;
      this.modalElement.noResultsTemplate = this.noResultsTemplate;
    }
  }

  handleModalBackdropClick(_event: MouseEvent) {
    this.core?.store.getState().setPopoverVisibility(false);
  }

  /**
   * When a hotkey is pressed, tests if the modifiers also match.
   * If modifiers match, toggles visibility of the popover modal.
   */
  handleHotkeyPressed(event: KeyboardEvent) {
    if (
      (event.ctrlKey && this.hotkeyModifier === 'ctrl') ||
      (event.altKey && this.hotkeyModifier === 'alt') ||
      (event.metaKey && this.hotkeyModifier === 'meta')
    ) {
      event.preventDefault();
      if (this.type === 'inline' && !this.isPopoverVisibleInState) {
        const hostElementInput = this.hostElement.querySelector(
          '.searchcraft-input-form-input',
        ) as HTMLInputElement | undefined;
        hostElementInput?.focus();
      } else {
        this.core?.store
          .getState()
          .setPopoverVisibility(!this.isPopoverVisibleInState);
      }
    }
  }

  handleCancelButtonClick() {
    this.core?.store.getState().setPopoverVisibility(false);
  }

  /**
   * Moves focus to the next/previous list item in the list view. If you are at the top
   * of the list view, it moves focus back to the input.
   *
   * @param direction
   */
  focusOnNextListItem(direction: 'ArrowDown' | 'ArrowUp') {
    // Results rendered by a `template` are reached through the first link in the template.
    const links = Array.from(
      document.querySelectorAll<HTMLElement>(
        '.searchcraft-popover-list-item-link, .searchcraft-popover-list-item-template',
      ),
    ).map((el) =>
      el.classList.contains('searchcraft-popover-list-item-template')
        ? el.querySelector('a')
        : el,
    );
    const listItems = Array.from(new Set(links)).filter(
      (el): el is HTMLAnchorElement =>
        !!el && !el.hasAttribute('disabled') && el.offsetParent !== null,
    );

    // Focus may be on another link inside a templated result, so match on the result too.
    const activeElement = document.activeElement;
    const currentIndex = listItems.findIndex(
      (el) =>
        el === activeElement ||
        !!el
          .closest('.searchcraft-popover-list-item-template')
          ?.contains(activeElement),
    );

    if (direction === 'ArrowDown') {
      listItems[(currentIndex + 1) % listItems.length]?.focus();
    } else if (direction === 'ArrowUp') {
      if (currentIndex >= 1) {
        listItems[currentIndex - 1]?.focus();
      } else {
        const input = document.querySelector('.searchcraft-input-form-input') as
          | HTMLInputElement
          | undefined;

        if (input) {
          input.focus();
          requestAnimationFrame(() => {
            input.selectionEnd = input.value.length;
            input.selectionStart = input.value.length;
          });
        }
      }
    }
  }

  get hasResultsToShow() {
    return (
      this.searchTerm &&
      this.searchTerm?.trim()?.length > 0 &&
      this.searchClientResponseItems.length > 0
    );
  }

  /**
   * Whether the search for the current search term finished without results.
   */
  get hasNoResultsToShow() {
    const searchTerm = this.searchTerm?.trim();

    return (
      !!searchTerm &&
      !this.isSearchInProgress &&
      this.searchClientResponseItems.length === 0 &&
      this.completedSearchTerm?.trim() === searchTerm
    );
  }

  renderNoResults() {
    const searchTerm = this.searchTerm?.trim() || '';

    if (this.noResultsTemplate) {
      try {
        return (
          <div
            class='searchcraft-popover-form-no-results'
            innerHTML={DOMPurify.sanitize(
              this.noResultsTemplate({ searchTerm }, { html, safeUrl }),
            )}
          />
        );
      } catch (error) {
        console.error('Invalid popover no results template:', error);
      }
    }

    return (
      <div class='searchcraft-popover-form-no-results'>
        <p class='searchcraft-popover-form-no-results-message'>
          No results found for "{searchTerm}".
        </p>
      </div>
    );
  }

  get viewAllResultsHref() {
    const baseUrl = this.viewAllResultsBaseUrl;
    if (!baseUrl) {
      return undefined;
    }

    const term = this.searchTerm?.trim();
    if (!term) {
      return baseUrl;
    }

    return `${baseUrl}${encodeURIComponent(term).replace(/%20/g, '+')}`;
  }

  get resolvedViewAllResultsLabel() {
    return this.viewAllResultsLabel ?? 'View All';
  }

  navigateToViewAllResults() {
    const href = this.viewAllResultsHref;

    if (!href || !this.hasResultsToShow) {
      return;
    }

    if (typeof window !== 'undefined') {
      window.location.href = href;
    }
  }

  renderInlinePopover() {
    const isListViewVisible = this.hasResultsToShow && this.isFocused;
    const isNoResultsVisible = this.hasNoResultsToShow && this.isFocused;
    const isDropdownVisible = isListViewVisible || isNoResultsVisible;

    return (
      <div
        class={classNames(
          'searchcraft-popover-form searchcraft-popover-form-inline',
          {
            'searchcraft-popover-form-active': isDropdownVisible,
          },
        )}
      >
        <div class='searchcraft-popover-form-input searchcraft-popover-form-inline-input'>
          <searchcraft-input-form
            onInputFocus={this.handleInputFocus.bind(this)}
            searchcraftId={this.searchcraftId}
            placeholderValue={this.placeholderValue}
            placeholderBehavior={this.placeholderBehavior}
          />
        </div>
        {isDropdownVisible && (
          <div class='searchcraft-popover-form-inline-wrapper'>
            <div class='searchcraft-popover-form-inline-scroll-area'>
              {isListViewVisible && this.showSummaryBox && (
                <searchcraft-results-summary
                  searchcraftId={this.searchcraftId}
                />
              )}
              {isListViewVisible ? (
                <searchcraft-popover-list-view
                  popoverResultMappings={this.popoverResultMappings}
                  template={this.template}
                  searchClientResponseItems={this.searchClientResponseItems}
                  adClientResponseItems={this.adClientResponseItems}
                  searchResultsPage={this.searchResultsPage}
                  searchResultsPerPage={this.searchResultsPerPage}
                  searchcraftId={this.searchcraftId}
                />
              ) : (
                this.renderNoResults()
              )}
            </div>
            <searchcraft-popover-footer
              searchcraftId={this.searchcraftId}
              sdkVariant={this.sdkVariant}
              viewAllResultsHref={this.viewAllResultsHref}
              viewAllResultsLabel={this.resolvedViewAllResultsLabel}
            />
          </div>
        )}
      </div>
    );
  }

  renderModalPopover() {
    if (this.isPopoverVisibleInState) {
      return (
        <div
          class={classNames(
            'searchcraft-popover-form searchcraft-popover-form-modal',
            {
              'searchcraft-popover-form-active':
                this.hasResultsToShow || this.hasNoResultsToShow,
            },
          )}
        >
          {/* biome-ignore lint/a11y/useKeyWithClickEvents: <explanation> */}
          <div
            class='searchcraft-popover-form-modal-backdrop'
            onClick={this.handleModalBackdropClick}
          />
          <div class='searchcraft-popover-form-modal-wrapper'>
            <div class='searchcraft-popover-form-input searchcraft-popover-form-modal-input'>
              <searchcraft-input-form
                onInputFocus={this.handleInputFocus.bind(this)}
                onInputInit={this.handleInputInit.bind(this)}
                searchcraftId={this.searchcraftId}
                placeholderValue={this.placeholderValue}
                placeholderBehavior={this.placeholderBehavior}
              />
              <button
                type='button'
                class='searchcraft-popover-form-cancel-button searchcraft-popover-form-modal-cancel-button'
                onClick={this.handleCancelButtonClick.bind(this)}
              >
                Cancel
              </button>
            </div>
            <div class='searchcraft-popover-form-modal-popover-list-view'>
              {this.showSummaryBox && this.hasResultsToShow && (
                <searchcraft-results-summary
                  searchcraftId={this.searchcraftId}
                />
              )}
              {this.hasResultsToShow && (
                <searchcraft-popover-list-view
                  popoverResultMappings={this.popoverResultMappings}
                  template={this.template}
                  searchClientResponseItems={this.searchClientResponseItems}
                  adClientResponseItems={this.adClientResponseItems}
                  searchResultsPage={this.searchResultsPage}
                  searchResultsPerPage={this.searchResultsPerPage}
                  searchcraftId={this.searchcraftId}
                />
              )}
              {this.hasNoResultsToShow && this.renderNoResults()}
            </div>
            <searchcraft-popover-footer
              searchcraftId={this.searchcraftId}
              sdkVariant={this.sdkVariant}
              viewAllResultsHref={this.viewAllResultsHref}
              viewAllResultsLabel={this.resolvedViewAllResultsLabel}
            />
          </div>
        </div>
      );
    }
  }

  renderFullscreenPopover() {
    if (this.isPopoverVisibleInState) {
      return (
        <div
          class={classNames(
            'searchcraft-popover-form searchcraft-popover-form-fullscreen',
            {
              'searchcraft-popover-form-active':
                this.hasResultsToShow || this.hasNoResultsToShow,
            },
          )}
        >
          <div class='searchcraft-popover-form-input searchcraft-popover-form-fullscreen-input'>
            <searchcraft-input-form
              onInputFocus={this.handleInputFocus.bind(this)}
              onInputInit={this.handleInputInit.bind(this)}
              searchcraftId={this.searchcraftId}
              placeholderValue={this.placeholderValue}
              placeholderBehavior={this.placeholderBehavior}
            />
            <button
              type='button'
              class='searchcraft-popover-form-cancel-button searchcraft-popover-form-fullscreen-cancel-button'
              onClick={this.handleCancelButtonClick.bind(this)}
            >
              Cancel
            </button>
          </div>
          <div class='searchcraft-popover-form-fullscreen-popover-list-view'>
            {this.showSummaryBox && this.hasResultsToShow && (
              <searchcraft-results-summary searchcraftId={this.searchcraftId} />
            )}
            {this.hasResultsToShow && (
              <searchcraft-popover-list-view
                popoverResultMappings={this.popoverResultMappings}
                template={this.template}
                searchClientResponseItems={this.searchClientResponseItems}
                adClientResponseItems={this.adClientResponseItems}
                searchResultsPage={this.searchResultsPage}
                searchResultsPerPage={this.searchResultsPerPage}
                searchcraftId={this.searchcraftId}
              />
            )}
            {this.hasNoResultsToShow && this.renderNoResults()}
          </div>
          <searchcraft-popover-footer
            searchcraftId={this.searchcraftId}
            sdkVariant={this.sdkVariant}
            viewAllResultsHref={this.viewAllResultsHref}
            viewAllResultsLabel={this.resolvedViewAllResultsLabel}
          />
        </div>
      );
    }
  }

  render() {
    switch (this.type) {
      case 'inline':
        return this.renderInlinePopover();
      case 'modal':
        return this.renderModalPopover();
      case 'fullscreen':
        return this.renderFullscreenPopover();
    }
  }
}
